CREATE TABLE accounts (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, name VARCHAR, status VARCHAR, currency VARCHAR);
CREATE TABLE advertisers (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, name VARCHAR, industry VARCHAR, parent_account VARCHAR);
CREATE TABLE campaigns (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, advertiser_id VARCHAR, name VARCHAR, status VARCHAR, start_day INTEGER, end_day INTEGER);
CREATE TABLE ad_groups (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, campaign_id VARCHAR, name VARCHAR, status VARCHAR);
CREATE TABLE ads (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, ad_group_id VARCHAR, creative_type VARCHAR, status VARCHAR);
CREATE TABLE keywords (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, ad_group_id VARCHAR, keyword_text VARCHAR, match_type VARCHAR);
CREATE TABLE audiences (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, name VARCHAR, segment_type VARCHAR, estimated_size BIGINT);
CREATE TABLE products (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, name VARCHAR, category VARCHAR, price DOUBLE);
CREATE TABLE marketplaces (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, name VARCHAR, region VARCHAR, currency VARCHAR);
CREATE TABLE campaign_config (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, campaign_id VARCHAR, delivery_state VARCHAR, objective VARCHAR, timezone VARCHAR);
CREATE TABLE budget_config (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, campaign_id VARCHAR, daily_limit DOUBLE, lifetime_limit DOUBLE, pacing VARCHAR);
CREATE TABLE bid_config (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, campaign_id VARCHAR, bid_type VARCHAR, base_bid DOUBLE, max_bid DOUBLE);
CREATE TABLE targeting_config (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, campaign_id VARCHAR, audience_id VARCHAR, marketplace_id VARCHAR, is_exclusion BOOLEAN);
CREATE TABLE conversion_config (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, campaign_id VARCHAR, attribution_window_days INTEGER, conversion_type VARCHAR, value_source VARCHAR);
CREATE TABLE impression_events (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, campaign_id VARCHAR, uid_hash VARCHAR, event_ts BIGINT, clicked INTEGER, converted INTEGER, attributed INTEGER, transformed_cost DOUBLE);
CREATE TABLE click_events (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, campaign_id VARCHAR, impression_id VARCHAR, event_ts BIGINT, click_position INTEGER);
CREATE TABLE conversion_events (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, campaign_id VARCHAR, impression_id VARCHAR, event_ts BIGINT, attribution_flag INTEGER, synthetic_value DOUBLE);
CREATE TABLE campaign_daily (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, campaign_id VARCHAR, day INTEGER, impressions BIGINT, clicks BIGINT, conversions BIGINT, attributed_conversions BIGINT, transformed_cost DOUBLE, attributed_value DOUBLE);
CREATE TABLE adgroup_daily (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, ad_group_id VARCHAR, day INTEGER, impressions BIGINT, clicks BIGINT, transformed_cost DOUBLE);
CREATE TABLE keyword_daily (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, keyword_id VARCHAR, day INTEGER, impressions BIGINT, clicks BIGINT, transformed_cost DOUBLE);
CREATE TABLE account_daily (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, day INTEGER, impressions BIGINT, clicks BIGINT, conversions BIGINT, transformed_cost DOUBLE);
CREATE TABLE auction_daily (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, marketplace_id VARCHAR, day INTEGER, auctions BIGINT, wins BIGINT, mean_bid DOUBLE);
