CREATE TABLE budget_policies (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, policy_text VARCHAR, severity VARCHAR, campaign_id VARCHAR);
CREATE TABLE bid_policies (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, policy_text VARCHAR, severity VARCHAR, campaign_id VARCHAR);
CREATE TABLE targeting_policies (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, policy_text VARCHAR, severity VARCHAR, audience_id VARCHAR);
