CREATE TABLE schema_versions (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, schema_version VARCHAR, change_note VARCHAR, effective_ts BIGINT);
CREATE TABLE metric_versions (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, metric_id VARCHAR, metric_version VARCHAR, effective_ts BIGINT);
CREATE TABLE data_freshness (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, source_table VARCHAR, watermark_ts BIGINT, freshness_sla_sec BIGINT);
CREATE TABLE permission_scope (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, subject_id VARCHAR, scope VARCHAR, revoked BOOLEAN);
