CREATE TABLE cache_versions (id VARCHAR PRIMARY KEY, tenant_id VARCHAR, account_id VARCHAR, valid_from BIGINT, valid_until BIGINT, record_version VARCHAR, provenance VARCHAR, is_generated BOOLEAN, cache_name VARCHAR, source_version VARCHAR, watermark_ts BIGINT);
